"use strict";
const assert=require("node:assert/strict"),fs=require("node:fs/promises"),os=require("node:os"),path=require("node:path");
const {GlobalPlanService}=require("../services/global-plan"),{emptyPlan,entryFor,identity}=require("../domain/global-plan"),{HubDataStore}=require("../services/data-store");
const storage=()=>{const data=new Map();return {getItem:k=>data.get(k)??null,setItem:(k,v)=>data.set(k,v),removeItem:k=>data.delete(k)}};
function fixture(saved=emptyPlan(),local=storage()){let disk=saved.version===1?require("../domain/plan-lifecycle").migrate(saved):structuredClone(saved);if(disk.version===2){delete disk.note;delete disk.entries;}if(disk.version===2&&!disk.activePlanId)disk=require("../domain/plan-lifecycle").create(disk);let fail=false,gate=null;const plugin={app:{vault:{adapter:{getBasePath:()=>"synthetic-vault"}}},projectWizard:{data:{globalPlan:structuredClone(disk)}},dataStore:{async updatePlan(mutate){if(gate)await gate;if(fail)throw Error("injected failure");const data={globalPlan:structuredClone(disk)};mutate(data);disk=data.globalPlan;return data;}}};const plan=new GlobalPlanService(plugin,{storage:local});return {plan,local,plugin,disk:()=>disk.version===2?{...disk,...(disk.plansById[disk.activePlanId]?.content??{note:"",entries:[]})}:disk,fail:v=>fail=v,gate:v=>gate=v};}
async function run(){
 let f=fixture();const file=entryFor("file",{path:"Research/a.pdf",sourceWorkspace:{type:"resource",id:"literature"}},{lastKnownLabel:"a.pdf"});assert.equal(f.plan.add([file,file]),1);await f.plan.flush();assert.equal(f.disk().entries.length,1);assert.equal(identity(f.disk().entries[0]),identity(file));
 f.plan.setNote("original text");f.plan.setNote("latest text");await f.plan.flush();assert.equal(f.disk().note,"latest text");assert.equal(f.plan.status,"Saved");
 f.fail(true);f.plan.setNote("recover this exact draft");await assert.rejects(f.plan.flush());assert.equal(await f.plan.closeSafe(),true);const restarted=fixture(f.disk(),f.local);assert.equal(restarted.plan.read().note,"recover this exact draft");await restarted.plan.flush();assert.equal(restarted.disk().note,"recover this exact draft");
 const local=storage(),conflicted=fixture(emptyPlan(),local);conflicted.fail(true);conflicted.plan.setNote("local draft");await assert.rejects(conflicted.plan.flush());const other=emptyPlan();other.revision=7;other.note="other writer";const recovered=fixture(other,local);assert.ok(recovered.plan.conflict);await recovered.plan.resolveConflict(false);assert.equal(recovered.plan.read().note,"other writer");
 f=fixture();let release;f.gate(new Promise(r=>release=r));f.plan.setNote("first");const inFlight=f.plan.flush();f.plan.setNote("second");release();await inFlight;assert.equal(f.disk().note,"second","old acknowledgements cannot replace new typing");
 f=fixture();const task=entryFor("task",{authorityId:"a",taskId:"t"},{lastKnownLabel:"Task"});f.plan.add([file,task]);await f.plan.flush();f.plan.remove(file.id);f.plan.setNote("preserve later typing");f.plan.undo();await f.plan.flush();assert.equal(f.disk().note,"preserve later typing");assert.equal(f.disk().entries.length,2);
 const broken=fixture(emptyPlan(),{getItem:()=>null,setItem:()=>{throw Error("local storage full")},removeItem(){}});broken.fail(true);broken.plan.setNote("still in memory");await assert.rejects(broken.plan.flush());assert.equal(await broken.plan.closeSafe(),false);assert.equal(broken.plan.read().note,"still in memory");
 const future=fixture({...emptyPlan(),version:99});assert(future.plan.readOnly);assert.equal(await future.plan.closeSafe(),true);assert.throws(()=>future.plan.setNote("no"));
 const root=await fs.mkdtemp(path.join(os.tmpdir(),"itacan-plan-"));try{const dir=path.join(root,".obsidian/plugins/test"),filePath=path.join(dir,"data.json");await fs.mkdir(dir,{recursive:true});await fs.writeFile(filePath,JSON.stringify({globalPlan:emptyPlan(),projectWorkRatings:{p:{d:2}},categories:[]}));const plugin={app:{vault:{adapter:{getBasePath:()=>root}}},manifest:{id:"test",dir},loadData:async()=>JSON.parse(await fs.readFile(filePath,"utf8"))};const store=new HubDataStore(plugin),initial=await store.load();await store.updatePlan(d=>{d.globalPlan.note="durable";d.globalPlan.revision++;});await store.save({...initial,unrelated:1});assert.equal(JSON.parse(await fs.readFile(filePath)).globalPlan.note,"durable");await assert.rejects(store.updatePlan(d=>d.categories=[{id:"bad"}]));await store.updateProgress(d=>d.projectWorkRatings.p.d=0);assert.equal(JSON.parse(await fs.readFile(filePath)).globalPlan.note,"durable");const before=await fs.readFile(filePath,"utf8"),write=store.atomicWrite;store.atomicWrite=async()=>{throw Error("disk full")};await assert.rejects(store.updatePlan(d=>d.globalPlan.note="lost"));assert.equal(await fs.readFile(filePath,"utf8"),before);store.atomicWrite=write;}finally{await fs.rm(root,{recursive:true,force:true});}
 console.log("PASS: plan atomic/stale saves, scoped boundary, rapid typing, failed saves, restart/conflicts and scoped Undo");
}
run().catch(e=>{console.error(e);process.exitCode=1});
